"""Editorial content for Aethus's original game. Reviewed 2026-10-29, v0.127.0.
No copied game assets, executable or inferred template values are published.
"""
P='/azeroth-survivors/'
def ref(key):return '{{s:'+key+'}}'
def a(path,label):return f'<a href="{P+path}">{label} →</a>'
def ext(url,label):return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{label} ↗<span class="sr-only"> (external website, opens in a new tab)</span></a>'
def para(text):return '<p>'+text+'</p>'
def steps(items):return '<ol>'+''.join('<li>'+x+'</li>' for x in items)+'</ol>'
def table(head,rows):return '<div class="table-wrap" tabindex="0" role="region" aria-label="Scrollable comparison"><table><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+x+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
